import React, { useState } from "react";
import Login from "./login";
import IncomeCategory from "./IncomeCategory";
import SpendingPriority from "./SpendingPriority";
import BudgetLimits from "./BudgetLimits";
import Dashboard from "./Dashboard";
import Preview from "./Preview";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    categories: [],
    limits: {}
  });

  return (
    <>
      {step === "login" && <Login onLogin={() => setStep("income")} />}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData({ ...data, income: val });
            setStep("priority");
          }}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          onNext={(cats) => {
            setData({ ...data, categories: cats });
            setStep("budget");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          selectedCategories={data.categories}
          onNext={(limits) => {
            setData({ ...data, limits });
            setStep("preview");
          }}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "preview" && (
        <Preview
          data={data}
          onEdit={() => setStep("income")}
          onConfirm={() => setStep("dashboard")}
        />
      )}

      {step === "dashboard" && <Dashboard />}
    </>
  );
}

export default App;
